using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class PierPaoloPasolini
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Finché io non sarò morto, nessuno potrà garantire di conoscermi veramente, cioè di potere dare un senso alla mia azione, che dunque, in quanto momento linguistico, è mal decifrabile.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Solo grazie alla morte, la nostra vita ci serve ad esprimerci.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "I pomeriggi che ho passato a giocare a pallone sui Prati di Caprara sono stati indubbiamente i più belli della mia vita. Mi viene quasi un nodo alla gola, se ci penso.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il ciclicsmo è lo sport più popolare perché non si paga il biglietto.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il complotto ci fa delirare. Ci libera da tutto il peso di confrontarci da soli con la verità.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il metodo più efficace sarebbe quello di abolire la televisione di Stato e di dare la possibilità di operare a delle televisioni private.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il senso di pace, di avventura che mi dà l'essere in questo albergo nell'interno di Ischia, è una di quelle cose che ormai la vita dà così raramente.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il successo non è niente. Il successo è l'altra faccia della persecuzione. E poi il successo è sempre una cosa brutta per un uomo.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il tipo di persone che amo di gran lunga di più sono le persone che possibilmente non abbiano fatto neanche la quarta elementare, cioè le persone assolutamente semplici.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "In realtà lo schema delle crisi giovanili è sempre identico: si ricostruisce a ogni generazione.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Voi giovani avete un unico dovere: quello di razionalizzare il senso di imbecillità che vi dànno i grandi, con le loro solenni Ipocrisie, le loro decrepite e faziose Istituzioni.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Altro non saprei consigliare ai giovani.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Io credo nel progresso, non credo nello sviluppo. E nella fattispecie in questo sviluppo. Ed è questo sviluppo, semmai, che dà alla mia natura gaia una svolta tremendamente triste, quasi tragica", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Bisogna volere il troppo per ottenere il poco.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "L'Italia – al di fuori naturalmente dei tradizionali comunisti – è nel suo insieme ormai un paese spoliticizzato, un corpo morto i cui riflessi non sono che meccanici.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "La borghesia si schiera sulle barricate contro se stessa, i “figli di papà” si rivoltano contro i “papà”. Sono dei borghesi rimasti tali e quali come i loro padri.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Lo Yemen, architettonicamente, è il paese più bello del mondo.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il puro medioevo, intorno.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Mio padre soffriva, ci faceva soffrire: odiava il mondo che aveva ridotto a due, tre dati ossessivi e inconciliabili: era uno che batteva continuamente, disperatamente, la testa contro un muro.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non ci dava ascolto, a me e a mia madre, perché ci disprezzava.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "La Resistenza e il Movimento Studentesco sono le due uniche esperienze democratiche-rivoluzionarie del popolo italiano.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Nel teatro la parola è doppiamente glorificata: è scritta, come nelle pagine di Omero, ma è anche pronunciata, come avviene fra due persone al lavoro: non c'è niente di più bello.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non c'è peccato peggiore, nel nostro tempo, che quello di rifiutarsi di capire: perché nel nostro tempo non si può scindere l'amare dal capire.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "L'invito evangelico che dice «ama il prossimo tuo come te stesso» va integrato con un «capisci il prossimo tuo come te stesso». Altrimenti l'amore è un puro fatto mistico e disumano.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non è neanche vero che la televisione modestamente sostituisca la tombola delle serate in famiglia", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "La televisione non è questo: essa ha nella sua funzione culturale tutta la prepotenza del potere; del potere industriale; che vuole, e determina e condiziona una serata familiare.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non ha importanza dove si è nati, quando come e dove si sono avuti i primi approcci con il calcio, per diventare un appassionato, un tifoso.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il tifo è una malattia giovanile che dura tutta la vita.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non posso più credere alla rivoluzione, ma non posso non stare dalla parte dei giovani che si battono per essa.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "È già un'illusione scrivere poesia, eppure continuo a scriverne, pure se per me la poesia non è più quel meraviglioso mito classico che ha esaltato la mia adolescenza.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non credo più nella dialettica e nella contraddizione, ma alle pure opposizioni.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Tuttavia sono sempre più affascinato da quell'alleanza esemplare che si compie nei santi, come san Paolo, fra vita attiva e vita contemplativa.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non soltanto non vedo differenza tra l'Edipo e Medea, ma non vedo nemmeno differenza tra Accattone e Medea, e nemmeno molta differenza tra il Vangelo e Medea.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Praticamente un autore fa sempre lo stesso film per un lungo periodo della sua vita, come uno scrittore scrive sempre la stessa poesia. Si tratta di varianti, anche profonde, di uno stesso tema.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Nulla è più anarchico del potere, il potere fa praticamente ciò che vuole.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "E ciò che il potere vuole è completamente arbitrario o dettato da sua necessità di carattere economico, che sfugge alle logiche razionali.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Io detesto soprattutto il potere di oggi. Ognuno odia il potere che subisce, quindi odio con particolare veemenza il potere di questi giorni.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "È un potere che manipola i corpi in un modo orribile, che non ha niente da invidiare alla manipolazione fatta da Himmler o da Hitler.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Poiché il cinema non è solo un'esperienza linguistica, ma, proprio in quanto ricerca linguistica, è un'esperienza filosofica.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Prevedo la spoliticizzazione completa dell'Italia: diventeremo un gran corpo senza nervi, senza più riflessi.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "La strada maestra, fatta di qualunquismo e di alienante egoismo, è già tracciata. Resterà forse, come sempre è accaduto in passato, qualche sentiero: non so però chi lo percorrerà, e come.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Renzo è una proiezione nostalgica del Manzoni, una figura di figlio-padre quale egli non è mai stato né mai avrebbe potuto essere: una possibilità perduta per sempre nel mondo.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Renzo è il simbolo della salute e dell'integrità.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Riparto, mi perdo nelle Calabrie: che si fanno sempre più Calabrie, sempre più Calabrie, finché a Pileto, a Palmi, comincia la Sicilia.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non c'è dubbio, non c'è il minimo dubbio che vorrei vivere qui: vivere e morirci, non di pace, come con Lawrence a Ravello, ma di gioia.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Non è mica una chiacchiera che qui profumano zagare e limoni, liquerizia e papiri.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il viaggio da Messina a Siracusa può fare impazzire.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Scendo per la cena: ma lì un profumo di limoni, una luna grossa come non l'ho mai vista, della gente che non aspetta altro che parlare, mi arresta.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "E solo perché ho parlato un po' con loro, dei loro problemi, del loro futuro.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Un bravo calciatore.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Questo odore della povera pelliccia di mia madre è l'odore della mia vita.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Erano giorni terribili: mia madre sentiva che Guido non sarebbe tornato più.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Centinaia di volte egli avrebbe potuto cadere combattendo contro i fascisti e i tedeschi: perché era un ragazzo di una generosità che non ammetteva nessuna debolezza, nessun compromesso.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Invece era destinato a morire in un modo più tragico ancora.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Egli morì in un modo che non mi regge il cuore di raccontare: avrebbe potuto anche salvarsi, quel giorno: è morto per correre in aiuto del suo comandante e dei suoi compagni.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Credo che non ci sia nessun comunista che possa disapprovare l'operato del partigiano Guido Pasolini.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Un atleta ha un solo modo per realizzare pienamente la propria libertà: lottare liberamente per vincere.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il calcio «è» un linguaggio con i suoi poeti e prosatori.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il gioco del football è una «sistema di segni»; è, cioè, una lingua, sia pure non verbale.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ebbene anche per la lingua del calcio si possono fare distinzioni del genere: anche il calcio possiede dei sottocodici, dal momento in cui, da puramente strumentale, diventa espressivo.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ci può essere un calcio come linguaggio fondamentalmente prosastico e un calcio come linguaggio fondamentalmente poetico.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ci sono nel calcio dei momenti che sono esclusivamente poetici: si tratta dei momenti dei «goal».", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ogni goal è sempre un'invenzione, è sempre una sovversione del codice: ogni goal è ineluttabilità, folgorazione, stupore, irreversibilità. Proprio come la parola poetica.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il capocannoniere del campionato è sempre il miglior poeta dell'anno.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Chaucer [...] non appartiene al popolo, anche se trae le sue storie dal popolo. Egli era già un borghese.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Il mondo di Chaucer e di Boccaccio non aveva sperimentato l'industrializzazione. Non c'era la società dei consumi, non c'erano le catene di montaggio.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "È impossibile capire che cosa io intenda fare con questi racconti inglesi, se non li si considera come il secondo film di una trilogia che comprende Il Decameron e Le mille e una notte.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ho cominciato a girare ''I racconti di Canterbury'' esattamente lo stesso giorno in cui in Italia è uscito ''Il Decameron'': per me non c'è stata soluzione di continuità.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Chaucer, come Boccaccio, è l'iniziatore di una letteratura [...]. Sin da ragazzo sono stato un appassionato studioso dei capiscuola delle varie letterature del mondo.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Questa volta me l'ero vista brutta [...]. Avevo temuto che il film non potesse uscire, o che mi fossero chiesti tagli impossibili da accettare.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Spesso ho avuto guai con la censura, mai però un rifiuto così reciso.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Da anni vengono fatte promesse solenni di abolire questa arcaica istituzione, ma niente cambia.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Insieme costituiscono un unico film [...] e sbagliano i critici se giudicano separate le singole pellicole.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Solo in apparenza manca ai miei ultimi film uno spessore politico [...].", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Avere scelto un diverso tipo di espressione credo sia un mio diritto.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ricordo e so che tanto io, giovane comunista della generazione precedente, che voi, giovani comunisti di oggi, se non conoscessimo Marx, Lenin e Gramsci, vivremmo una vita senza forma.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ricordo e so che l'unica possibilità di operare, oltre che di pensare, è data non solo dall'alternativa rivoluzionaria offerta dal marxismo, ma soprattutto dalla sua alterità.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ricordo e so che il quadro umano è cambiato, che le coscienze sono state violate nel profondo.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ricordo e so che, a compensare questa strage umana, non ci sono né ospedali né scuole, né verde né asili per i vecchi e i bambini, né cultura né alcuna dignità possibile.", Author = "Pier Paolo Pasolini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Pier_Paolo_Pasolini", Text = "Ricordo e so di colpo che si è avverato", Author = "Pier Paolo Pasolini" },
        };
    }
}